<script setup lang="ts">
import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api,post,fmt,downloadText} from '../api/client';
const route=useRoute(),method=ref('voltage'),timeBlock=ref(4),result=ref<any>(null),cmdp=ref<any>(null),busy=ref(false),error=ref('');
async function preview(){busy.value=true;error.value='';try{result.value=await post('/aggregation/preview',{task_id:typeof route.query.task==='string'?route.query.task:null,node_method:method.value,time_block:timeBlock.value});}catch(e:any){error.value=e.message}finally{busy.value=false;}}
onMounted(async()=>{await preview();try{cmdp.value=await api('/research/cmdp')}catch(e:any){error.value=e.message}});
</script>
<template><div class="page-heading"><div><div class="eyebrow">M9–M10 / 聚合、分解与智能决策</div><h1>聚合与研究模块</h1><p>节点分组、时间聚合与子任务组织</p></div><RouterLink :to="route.query.task?'/workbench?task='+route.query.task:'/workbench'">返回建模工作台 ↗</RouterLink></div>
 <section class="panel panel-pad"><div class="section-heading"><h2>节点与时空聚合</h2><span class="status-chip ready">分组预览</span></div><div class="v4-actions"><el-select v-model="method" style="width:180px"><el-option value="voltage" label="按电压等级分组"/><el-option value="area" label="按区域编号分组"/></el-select><el-select v-model="timeBlock" style="width:150px"><el-option v-for="n in [1,2,4,8,16]" :key="n" :value="n" :label="n+' 时段 / 组'"/></el-select><el-button type="primary" :loading="busy" @click="preview" data-testid="aggregation-preview">生成聚合预览</el-button><el-button v-if="result" @click="downloadText('aggregation.json',JSON.stringify(result,null,2))">导出分组</el-button></div><div v-if="error" class="notice amber">{{error}}</div>
 <template v-if="result"><div class="two-columns"><div><h3>节点分组</h3><el-table :data="result.node_groups" max-height="350"><el-table-column prop="name" label="分组"/><el-table-column prop="bus_count" label="母线"/><el-table-column prop="generator_count" label="机组"/><el-table-column label="负荷 / MW"><template #default="{row}">{{fmt(row.pd_mw)}}</template></el-table-column></el-table></div><div><h3>时间聚合</h3><el-table :data="result.time_groups" max-height="350"><el-table-column label="时段"><template #default="{row}">{{row.periods[0]}}–{{row.periods.at(-1)}}</template></el-table-column><el-table-column prop="minutes" label="分钟"/><el-table-column label="平均负荷 / MW"><template #default="{row}">{{fmt(row.mean_pd_mw)}}</template></el-table-column></el-table></div></div><div class="v4-actions"><span v-if="result.single_snapshot" class="status-chip">单断面演示模式</span><span class="status-chip">等值网架生成 · 待开发</span></div></template></section>
 <div class="research-cards" style="margin-top:20px"><section class="panel"><h2>知识增强问题分解</h2><span class="status-chip">待开发</span><p>规则检索 → 分解策略 → 子问题编排</p><div v-for="t in result?.subtasks||[]" :key="t.id" class="key-value"><span>{{t.name}}</span><span>{{t.status}}</span></div></section><section class="panel"><h2>子问题安全智能体</h2><span class="status-chip">待开发</span><p>安全约束学习、物理约束内化与大模型反馈</p><p>任务 3 · 中期后开展</p></section><section class="panel"><h2>多智能体协同</h2><span class="status-chip">待开发</span><p>边端协同、知识共享与全局优化协调</p><p>任务 4 · 中期后开展</p></section></div>
 <section class="panel panel-pad" style="margin-top:20px" data-testid="cmdp-panel"><div class="section-heading"><h2>OTS → CMDP</h2><span class="status-chip">待开发 / 理想目标</span></div><div v-if="cmdp" class="research-cards"><div><h3>状态与动作</h3><p>{{cmdp.state.join(' · ')}}</p><p>{{cmdp.action.join(' · ')}}</p></div><div><h3>奖励与约束代价</h3><p>{{cmdp.reward.join(' · ')}}</p><p>{{cmdp.cost.join(' · ')}}</p></div><div><h3>状态转移</h3><p>{{cmdp.transition}}</p><span class="status-chip">强化学习训练 · 中期后开展</span></div></div></section>
</template>
